TLM.f("Sancti/08-29cc",{"officium":"S. Sabinæ Martyris","rule":["vide C7;"],"ruleInherited":["Psalmi Dominica","Antiphonas horas"],"fallback":"Commune/C7","sections":{"Oratio":[{"k":"text","la":"Deus, qui inter cétera poténtiae tuae mirácula étiam in sexu frágili victóriam martýrii contulísti: concéde propítius; ut, qui beátae Sabínae Mártyris tuae natalícia cólimus, per eius ad te exémpla gradiámur."},{"k":"macro","name":"Per Dominum"}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, beátæ Sabínæ Mártyris tuæ dicátas méritis, benígnus assúme: et ad perpétuum nobis tríbue proveníre subsídium."},{"k":"macro","name":"Per Dominum"}],"Postcommunio":[{"k":"text","la":"Divíni muneris largitáte satiáti, quǽsumus, Dómine, Deus noster: ut, intercedénte beáta Sabína Mártyre tua, in ejus semper participatióne vivámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"d3abd225104c2469":{"t":"<i>Pomolimo se</i>.\nBože, koje si između ostalih čudesa svoje moći dao i slabom spolu mučeničku pobjedu, dopusti blagostivo da mi koji slavimo rođendan za nebo blažene Sabine, tvoje mučenice, idemo k tebi po njezinu primjeru.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si među ostalim čudesima svoje moći 1 slabom spolu podao pobjedu mučeništva, dopusti milostivo, da svetkujući rođeni dan blažene I., Tvoje mučenice, slijedimo njezin primjer i tako dođemo k Tebi, po G. n.","knRef":"Kniewald 1942, str. 828–829 (snimka 415) (OCR)"},"7e188b7f0c888706":{"t":"Dobrostivo primi, Gospodine, žrtvene darove koje ti posvećujemo po zaslugama blažene Sabine, tvoje mučenice, i daj da nam budu na neprestanu pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, blagostivo žrtve, što Ti ih prinosimo zaslugama blažene I., djevice i mučenice 1 podaj, da nam ishode Tvoju neprestanu pomoć. Po G. n.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"ea41eb2d985c1af3":{"t":"<i>Pomolimo se</i>.\nNasićeni obilnim Božjim darovima, molimo, Gospodine Bože naš, da po zagovoru blažene Sabine, tvoje mučenice, uvijek živimo sudjelujući u njima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
